'use strict';
const novaAuth={epoch:0,requests:new Set(),stage:'loading',session:null,username:'',busy:false,employees:null,point:null,report:null,serverOffset:0,lastCheck:0};
const originalNovaCloseModal=closeModal;closeModal=function(){originalNovaCloseModal();document.getElementById('modal').innerHTML=''};
const novaRoles={admin:'Administrador',manager:'Gestor da frota',employee:'Funcionário'};
const novaDate=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(Date.now()+novaAuth.serverOffset));
const novaClock=at=>new Intl.DateTimeFormat('pt-BR',{timeZone:'America/Sao_Paulo',hour:'2-digit',minute:'2-digit',second:'2-digit'}).format(at?new Date(at):new Date(Date.now()+novaAuth.serverOffset));
const novaButton=(action,label,extra='',primary=false)=>`<button type="button" class="${primary?'primary':''}" data-nova-action="${action}" ${extra}>${esc(label)}</button>`;
function novaNavigation(){if(novaAuth.session?.user?.role==='employee')return [['point','Meu ponto','clock'],['school','Chamadas','bus']];const list=[['fleet','Frota','bus'],['school','Chamadas','grid'],['point','Meu ponto','clock']];if(novaAuth.session?.user?.role==='admin')list.push(['employees','Equipe','user']);return [...list,['alerts','Alertas','bell'],['fuel','Abastecimentos','fuel'],['reports','Resumo','chart'],['settings','Ajustes','settings']]}
function novaCurrentUser(){return novaAuth.session?.user||null}
function novaInvalidateRequests(){novaAuth.epoch++;for(const controller of novaAuth.requests)controller.abort();novaAuth.requests.clear()}
function novaCaptureSession(){return {epoch:novaAuth.epoch,userId:novaCurrentUser()?.id}}
function novaSessionCurrent(token){return token.epoch===novaAuth.epoch&&token.userId===novaCurrentUser()?.id}
function novaSetSession(session){if(novaAuth.session?.user?.id!==session.user?.id||novaAuth.session?.csrf!==session.csrf)novaInvalidateRequests();novaAuth.session=session;novaAuth.serverOffset=Date.parse(session.serverTime)-Date.now();novaAuth.lastCheck=Date.now()}
function novaClearFleet(){novaInvalidateRequests();if(typeof schoolReset==='function')schoolReset();novaAuth.fleetEvents?.close();novaAuth.fleetEvents=null;novaAuth.point=null;novaAuth.punching=false;novaAuth.report=null;novaAuth.adminReport=null;novaAuth.employees=null;novaAuth.pendingPunch=null;pendingChanges=false;saving=false;pulling=false;equipmentDirty=false;state=emptyState();selected=null;sharedBase=null;sharedRevision=0;activeProfileId='';try{localStorage.removeItem(KEY+'-shared-cache');localStorage.removeItem(PROFILE_KEY)}catch{}}
function novaNotifyTabs(){try{localStorage.setItem('nova-alianca-auth-event',String(Date.now())+Math.random())}catch{}}
function renderNovaAccess(error=''){
 const s=novaAuth.stage,session=novaAuth.session,setup=s==='setup',change=s==='password',forced=!!session?.user?.mustChangePassword;
 const heading=setup?'Preparar o acesso da equipe':change?(forced?'Escolha sua senha':'Trocar minha senha'):'Entre na sua conta';
 let form='';if(s==='loading')form='<p class="help" role="status">Conectando à empresa…</p>';else if(setup&&!session?.canSetup)form='<p>O primeiro administrador deve ser criado no PC servidor.</p><p class="help">Nesse PC, abra <strong>http://127.0.0.1:4174/</strong>. Depois, os funcionários entram com o login e a senha fornecidos pela administração.</p>'+novaButton('reconnect-auth','Tentar novamente','',true);
 else if(setup)form=`<form id="nova-access-form"><p class="help">Crie a conta de quem administrará os acessos. A frota e os históricos existentes serão preservados.</p>${session.bootstrapProfiles?.length?`<label>Vincular a um perfil já existente (opcional)<select name="profileId"><option value="">Criar nova identificação</option>${session.bootstrapProfiles.map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('')}</select></label>`:''}<label>Nome completo<input name="name" autocomplete="name" required maxlength="80"></label><label>Login<input name="username" value="administrador" autocomplete="username" required minlength="3" maxlength="80" autocapitalize="none" spellcheck="false"></label><label>Sua senha<input name="password" type="password" autocomplete="new-password" required minlength="10" maxlength="128"></label><label>Repita sua senha<input name="confirm" type="password" autocomplete="new-password" required minlength="10" maxlength="128"></label><p class="help">Use ao menos 10 caracteres. Esta é a sua senha pessoal; as senhas temporárias dos funcionários serão geradas depois.</p><p class="error" id="nova-access-error" role="alert">${esc(error)}</p><button class="primary" type="submit">Criar administrador</button></form>`;
 else if(change)form=`<form id="nova-access-form"><p class="help">${forced?'A senha temporária precisa ser substituída antes de usar a conta.':'Escolha uma senha pessoal que só você saiba.'}</p>${!forced?'<label>Senha atual<input name="currentPassword" type="password" autocomplete="current-password" required></label>':''}<label>Nova senha<input name="newPassword" type="password" autocomplete="new-password" minlength="10" maxlength="128" required></label><label>Repita a nova senha<input name="confirm" type="password" autocomplete="new-password" minlength="10" maxlength="128" required></label><p class="help">Use de 10 a 128 caracteres.</p><p class="error" id="nova-access-error" role="alert">${esc(error)}</p><button class="primary" type="submit">Salvar minha senha</button>${forced?'':novaButton('cancel-password','Cancelar')}</form>`;
 else form=`<form id="nova-access-form"><p class="help">Use o login e a senha fornecidos pela administração.</p><label>Login<input name="username" value="${esc(novaAuth.username)}" autocomplete="username" required maxlength="80" autocapitalize="none" spellcheck="false"></label><label>Senha<input name="password" type="password" autocomplete="current-password" required maxlength="128"></label><p class="error" id="nova-access-error" role="alert">${esc(error)}</p><button class="primary" type="submit">Entrar</button>${novaButton('forgot-password','Esqueci minha senha')}</form>`;
 document.getElementById('app').innerHTML=`<main class="nova-access"><aside class="na-welcome"><span class="na-welcome-label">NOVA ALIANÇA TRANSPORTES</span><h2>Cada caminho começa com cuidado.</h2><p>Gente, veículos e compromissos.<br>O dia a dia da nossa equipe, no mesmo lugar.</p><img src="nova-alianca-route.svg" alt="" class="na-route-art"><span class="na-welcome-city">MOGI DAS CRUZES · SÃO PAULO</span></aside><section class="nova-access-card"><img class="nova-access-logo" src="nova-alianca-logo.svg" alt="Nova Aliança Transportes"><h1>${heading}</h1>${form}<p class="nova-access-foot">Nova Aliança Transportes · Mogi das Cruzes</p></section></main>`;
 const element=document.getElementById('nova-access-form');if(!element)return;
 element.elements.profileId?.addEventListener('change',()=>{const p=session.bootstrapProfiles.find(p=>p.id===element.elements.profileId.value);if(p)element.elements.name.value=p.name});
 element.addEventListener('submit',async e=>{e.preventDefault();if(novaAuth.busy)return;const f=new FormData(element),button=element.querySelector('[type="submit"]'),output=document.getElementById('nova-access-error');novaAuth.busy=true;button.disabled=true;output.textContent='';try{
  if(setup){if(f.get('password')!==f.get('confirm'))throw Error('As senhas precisam ser iguais.');const value=await requestShared('/api/auth/setup',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:f.get('name'),username:f.get('username'),password:f.get('password'),profileId:f.get('profileId')||null,punchMode:'four'})});novaSetSession(value);novaNotifyTabs();await novaEnter()}
  else if(change){if(f.get('newPassword')!==f.get('confirm'))throw Error('As senhas precisam ser iguais.');await requestShared('/api/auth/password',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({currentPassword:f.get('currentPassword')||'',newPassword:f.get('newPassword')})});novaAuth.username=session.user.username;novaAuth.session=null;novaAuth.stage='login';novaClearFleet();novaNotifyTabs();renderNovaAccess();toast('Senha atualizada. Entre com a sua nova senha.')}
  else{const owner=localRead('nova-alianca-draft-owner');if(localRead(DRAFT_KEY)&&owner){const data=JSON.parse(owner);if(data.username!==String(f.get('username')).trim().toLowerCase())throw Error('Há alterações não salvas de outra conta. Entre nela primeiro para salvá-las.')}novaAuth.username=String(f.get('username')).trim().toLowerCase();const value=await requestShared('/api/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:novaAuth.username,password:f.get('password')})});novaSetSession(value);novaNotifyTabs();await novaEnter()}
 }catch(error){if(output.isConnected)output.textContent=error.message;else toast(error.message)}finally{novaAuth.busy=false;if(button.isConnected)button.disabled=false}});
}
async function novaEnter(){const user=novaCurrentUser();if(!user){novaAuth.stage='login';return renderNovaAccess()}if(user.mustChangePassword){novaAuth.stage='password';return renderNovaAccess()}novaAuth.stage='ready';novaAuth.point=null;novaAuth.report=null;novaAuth.employees=null;activeProfileId=user.profileId||'';try{localStorage.removeItem(CACHE_KEY);if(activeProfileId)localStorage.setItem(PROFILE_KEY,activeProfileId)}catch{}
 if(user.role==='employee'){novaClearFleet();page='point';sharedStatus='online';shell();await loadNovaPoint()}else{page='fleet';await bootShared();const legacy=localRead(KEY);if(legacy&&localStorage.getItem(MIGRATION_KEY)===migrationFingerprint(legacy))localStorage.removeItem(KEY)}startNovaUpdates()}
async function refreshNovaSetup(){
 if(novaAuth.stage!=='setup'||novaAuth.busy||novaAuth.setupChecking||document.visibilityState!=='visible')return;
 novaAuth.setupChecking=true;
 try{const session=await requestShared('/api/auth/session');if(novaAuth.stage!=='setup'||novaAuth.busy)return;if(session.initialized){novaSetSession(session);if(session.user)await novaEnter();else{novaAuth.stage='login';renderNovaAccess()}}else if(session.canSetup!==novaAuth.session?.canSetup){novaSetSession(session);renderNovaAccess()}}
 catch{}finally{novaAuth.setupChecking=false}
}
let novaSetupUpdatesStarted=false;
function startNovaSetupUpdates(){if(novaSetupUpdatesStarted)return;novaSetupUpdatesStarted=true;setInterval(refreshNovaSetup,4000);document.addEventListener('visibilitychange',refreshNovaSetup);window.addEventListener('focus',refreshNovaSetup)}
async function bootNova(){startNovaSetupUpdates();novaAuth.stage='loading';novaClearFleet();renderNovaAccess();try{const session=await requestShared('/api/auth/session');novaSetSession(session);if(!session.initialized){novaAuth.stage='setup';renderNovaAccess()}else if(!session.user){novaAuth.stage='login';renderNovaAccess()}else await novaEnter()}catch(e){if(e.staleSession)return;novaAuth.stage='login';renderNovaAccess(e.message)}}
function novaExpired(){novaAuth.username=novaCurrentUser()?.username||novaAuth.username;novaAuth.session=null;novaAuth.stage='login';novaClearFleet();if(document.getElementById('modal').open)closeModal();renderNovaAccess('Entre novamente para continuar.');novaNotifyTabs()}
async function novaLogout(){if(pendingChanges)throw Error('Salve ou exporte as alterações pendentes antes de sair.');await requestShared('/api/auth/logout',{method:'POST'});novaAuth.session=null;novaAuth.stage='login';novaClearFleet();novaAuth.point=null;novaAuth.report=null;novaAuth.employees=null;closeModal();renderNovaAccess();novaNotifyTabs()}
function novaAccountMenu(){const u=novaCurrentUser();if(!u)return bootNova();profileDialog('Sua conta',u.name,`<p><strong>${esc(novaRoles[u.role])}</strong> · ${esc(u.username)}</p><div class="profile-options">${novaButton('go-point','Meu ponto')}${u.role==='admin'?novaButton('go-employees','Administrar equipe'):''}${u.role==='admin'?novaButton('recovery-codes','Códigos de recuperação'):''}${novaButton('change-password','Trocar minha senha')}${novaButton('logout','Sair desta conta')}</div>`)}
currentProfile=function(){const u=novaCurrentUser();return u?{id:u.profileId||u.id,name:u.name,title:u.title,photo:(state.profiles||[]).find(p=>p.id===u.profileId)?.photo||u.photo||''}:null};
profileControl=function(){const p=currentProfile();return `<button type="button" class="profile-control" data-nova-action="account" aria-label="Minha conta">${profileAvatar(p)}<span class="profile-copy"><strong>${esc(p?.name||'Minha conta')}</strong><small>${esc(novaRoles[novaCurrentUser()?.role]||'')}</small></span></button>`};
requireActiveProfile=function(){if(novaCurrentUser()&&!novaCurrentUser().mustChangePassword)return true;bootNova();return false};
ensureProfileChoice=function(){};
openProfilePicker=novaAccountMenu;openProfileMenu=novaAccountMenu;
teamView=function(){return `<section class="panel"><h2>Contas da equipe</h2><p class="help">Cada pessoa acessa com seu login e senha. Funcionários consultam o próprio ponto; gestores acessam a frota; administradores cuidam dos acessos e horários.</p>${novaCurrentUser()?.role==='admin'?novaButton('go-employees','Administrar equipe','',true):novaButton('account','Minha conta')}</section>`};
function novaEmployeesView(){if(novaCurrentUser()?.role!=='admin')return '<p>Acesso restrito à administração.</p>';const value=novaAuth.employees;if(!value)return pageHead('Equipe','Carregando funcionários…');return `${pageHead('Equipe','Contas, horários e acompanhamento da jornada.',novaButton('employee-new','Cadastrar funcionário','',true))}<section class="panel"><div class="section-head"><div><h2>Acesso ao ponto</h2><p class="help">${value.employees.filter(e=>e.active).length} conta(s) ativa(s). Registros de jornada são individuais.</p></div>${novaButton('network-settings','Rede e exceções')}</div><p class="help">Entrada, saída para almoço, volta do almoço e saída. Horário fixo por dia da semana; exceções por data podem ser cadastradas.</p></section><section class="panel"><div class="nova-employee-list">${value.employees.map(e=>`<article class="nova-employee"><div><strong>${esc(e.name)}</strong><p>${esc(e.title||novaRoles[e.role])} · Login: ${esc(e.username)}${e.employeeCode?' · Matrícula: '+esc(e.employeeCode):''}</p><div class="actions">${badge(e.active?'green':'pending',e.active?'Ativo':'Inativo')}${badge('pending',novaRoles[e.role])}${e.mustChangePassword?badge('yellow','Troca de senha pendente'):''}${e.remotePointAllowed?badge('yellow','Exceção de rede autorizada'):''}</div></div><div class="actions">${novaButton('employee-edit','Editar',`data-employee="${esc(e.id)}"`)}${novaButton('schedule','Horário',`data-employee="${esc(e.id)}"`)}${novaButton('employee-report','Jornada',`data-employee="${esc(e.id)}"`)}${e.id!==novaCurrentUser().id?novaButton('employee-password','Nova senha temporária',`data-employee="${esc(e.id)}"`):''}</div></article>`).join('')}</div></section>${novaAdminReportView()}`}
async function loadNovaEmployees(){const token=novaCaptureSession(),value=await requestShared('/api/people');if(!novaSessionCurrent(token))return;novaAuth.employees=value;if(page==='employees'&&novaAuth.stage==='ready')shell()}
function novaEmployeeForm(id){const value=novaAuth.employees,e=id?value.employees.find(e=>e.id===id):null;if(id&&!e)return;const profiles=(value.profiles||[]).filter(p=>!value.employees.some(e=>e.profileId===p.id));modal(e?'Editar funcionário':'Cadastrar funcionário','O acesso é individual. A senha temporária será mostrada uma única vez.',field('name','Nome completo','text',e?.name||'','required maxlength="80"',true)+field('username','Login','text',e?.username||'','required minlength="3" maxlength="80" autocapitalize="none" autocomplete="off"')+field('employeeCode','Matrícula (opcional)','text',e?.employeeCode||'','maxlength="60"')+field('title','Cargo / função (opcional)','text',e?.title||'','maxlength="80"')+opsSelect('role','Acesso',[['employee','Funcionário — próprio ponto'],['manager','Gestor — frota e próprio ponto'],['admin','Administrador — equipe, frota e ponto']],e?.role||'employee')+opsSelect('punchMode','Marcações',[['four','Entrada, almoço, retorno e saída'],['two','Entrada e saída'],['flex','Marcações flexíveis']],e?.punchMode||'four')+(!e&&profiles.length?opsSelect('profileId','Perfil anterior (opcional)',[['','Criar nova identificação'],...profiles.map(p=>[p.id,p.name])],'',false):'')+`<label class="check full"><input name="remotePointAllowed" type="checkbox" ${e?.remotePointAllowed?'checked':''}>Autorizar esta pessoa a bater ponto fora da rede da empresa</label>`+opsArea('networkExceptionNote','Motivo da exceção de rede (opcional)',e?.networkExceptionNote||'',false,500)+(e?`<label class="check full"><input name="active" type="checkbox" ${e.active?'checked':''}>Conta ativa</label>`:'')+'<p class="help full">A exceção não cria conexão remota. Fora da empresa, o aplicativo precisa estar acessível por um meio seguro.</p>',async f=>{const input={name:f.get('name').trim(),username:f.get('username').trim().toLowerCase(),employeeCode:f.get('employeeCode').trim(),title:f.get('title').trim(),role:f.get('role'),punchMode:f.get('punchMode'),remotePointAllowed:f.get('remotePointAllowed')==='on',networkExceptionNote:f.get('networkExceptionNote').trim(),...(!e?{profileId:f.get('profileId')||null}:{active:f.get('active')==='on'})};const result=await requestShared('/api/people'+(e?'/'+e.id:''),{method:e?'PATCH':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(input)});closeModal();await loadNovaEmployees();if(!e)novaShowTemporary(result);else{toast('Conta atualizada.');if(e.id===novaCurrentUser().id)await bootNova()}},e?'Salvar alterações':'Criar conta')}
function novaShowTemporary(result){const u=result.user;profileDialog('Acesso criado',u.name,`<p class="help">Entregue estes dados somente ao funcionário. A senha deve ser trocada no primeiro acesso e expira em 7 dias.</p><label>Login<input readonly value="${esc(u.username)}"></label><label>Senha temporária<input readonly value="${esc(result.temporaryPassword)}" autocomplete="off"></label><p class="help">Depois de fechar esta tela, a senha não poderá ser consultada. Você poderá gerar outra.</p>`,novaButton('schedule','Definir horário',`data-employee="${esc(u.id)}"`,true)+novaButton('close-nova','Fechar'))}
function novaResetPassword(id){const e=novaAuth.employees.employees.find(e=>e.id===id);if(!e)return;modal('Gerar nova senha temporária',e.name,`<p class="full">A senha anterior deixará de funcionar e as sessões abertas dessa conta serão encerradas. O funcionário escolherá uma nova senha no próximo acesso.</p>`,async()=>{const result=await requestShared('/api/people/'+id+'/password',{method:'POST'});closeModal();await loadNovaEmployees();novaShowTemporary(result)},'Gerar senha temporária')}
function novaNetworkSettings(){const config={...novaAuth.employees.configuration,currentNetwork:novaAuth.session?.configuration?.currentNetwork};modal('Rede da empresa','As marcações são validadas pela rede de origem no servidor.',`<p class="help full">O celular precisa estar conectado a uma rede autorizada. A maioria dos Wi-Fis da mesma empresa usa a mesma rede local. Exceções são definidas no cadastro de cada funcionário.</p>${novaAuth.session?.hosted?`<p class="help full">Online, o ponto verifica o endereço público da conexão da empresa. Cadastre essa conexão estando no Wi-Fi da empresa.${config.currentNetwork?' Endereço atual: <strong>'+esc(config.currentNetwork)+'</strong>.':''}</p>${config.currentNetwork?'<button type="button" data-nova-action="use-current-network">Adicionar rede desta conexão</button>':''}`:''}<details class="full" ${novaAuth.session?.hosted?'open':''}><summary>Configuração avançada da rede</summary>${opsArea('networks','Redes autorizadas (uma por linha)',config.allowedNetworks.join('\n'),true,500)}<p class="help">Exemplo: 192.168.1.0/24. Confirme com quem administra os roteadores antes de mudar. O endereço informado pelo próprio navegador não é usado como prova.</p></details>`,async f=>{const allowedNetworks=f.get('networks').split(/[\n,;]/).map(s=>s.trim()).filter(Boolean);await requestShared('/api/time/settings',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({markingChannel:'lan',allowedNetworks})});closeModal();await loadNovaEmployees();toast('Redes autorizadas atualizadas.')})}
let novaUpdatesStarted=false;
function startNovaUpdates(){if(novaUpdatesStarted)return;novaUpdatesStarted=true;setInterval(async()=>{if(novaAuth.stage!=='ready'||document.visibilityState!=='visible'||document.getElementById('modal').open||novaAuth.busy)return;try{const session=await requestShared('/api/auth/session');if(!session.user||session.user.id!==novaCurrentUser()?.id||session.user.role!==novaCurrentUser()?.role)return bootNova();novaSetSession(session);if(page==='point')await loadNovaPoint(false)}catch{}},20000);setInterval(()=>{const node=document.getElementById('nova-clock');if(node)node.textContent=novaClock()},1000);window.addEventListener('storage',e=>{if(e.key==='nova-alianca-auth-event')bootNova()})}
async function novaGo(target){if(target==='employees'&&novaCurrentUser()?.role!=='admin')return;if(pendingChanges)throw Error('Salve as alterações pendentes antes de trocar de área.');closeModal();selected=null;page=target;shell();if(target==='point')await loadNovaPoint();if(target==='employees')await loadNovaEmployees();if(target==='school')await loadSchool()}
document.addEventListener('click',e=>{const legacy=e.target.closest('[data-profile-action]');if(legacy){e.preventDefault();e.stopImmediatePropagation();return novaAccountMenu()}const navigation=e.target.closest('[data-action="nav"]');if(navigation&&['point','employees','school'].includes(navigation.dataset.id)){e.preventDefault();e.stopImmediatePropagation();return novaGo(navigation.dataset.id).catch(error=>toast(error.message))}const b=e.target.closest('[data-nova-action]');if(!b)return;e.preventDefault();e.stopImmediatePropagation();const action=b.dataset.novaAction,id=b.dataset.employee;let promise;try{switch(action){case'reconnect-auth':promise=bootNova();break;case'account':return novaAccountMenu();case'forgot-password':return novaRecoveryForm();case'recovery-codes':return novaRecoveryCodes();case'backup-full':return novaCompleteBackup();case'restore-full':return novaRestoreBackup();case'logout':promise=novaLogout();break;case'change-password':if(pendingChanges)throw Error('Salve as alterações pendentes antes de trocar sua senha.');closeModal();novaAuth.stage='password';return renderNovaAccess();case'cancel-password':novaAuth.stage='ready';return shell();case'go-point':promise=novaGo('point');break;case'go-employees':promise=novaGo('employees');break;case'employee-new':return novaEmployeeForm();case'employee-edit':return novaEmployeeForm(id);case'employee-password':return novaResetPassword(id);case'network-settings':return novaNetworkSettings();case'use-current-network':{const network=novaAuth.session?.configuration?.currentNetwork;if(!network)return;const field=document.querySelector('#modal-form [name="networks"]');const values=field.value.split(/[\n,;]/).map(s=>s.trim()).filter(Boolean);if(!values.includes(network))values.push(network);field.value=values.join('\n');return toast('Rede adicionada ao formulário. Confira e salve para autorizar.')}case'schedule':promise=novaEditSchedule(id);break;case'employee-report':promise=novaLoadAdminReport(id);break;case'close-nova':return closeModal();default:return novaTimeAction(action,b)}if(promise?.catch)promise.catch(error=>toast(error.message))}catch(error){toast(error.message)}},true);

function novaRecoveryCodes(){modal('Códigos de recuperação','Guarde-os fora do aplicativo, em local privado.',field('currentPassword','Sua senha atual','password','','required autocomplete="current-password"',true)+'<p class="help full">Serão gerados seis códigos de uso único. Eles permitem recuperar sua conta de administrador se esquecer a senha. Gerar novamente invalida os códigos anteriores.</p>',async f=>{const value=await requestShared('/api/auth/recovery-codes',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({currentPassword:f.get('currentPassword')})});novaDownload('Nova Aliança · Códigos de recuperação\nLogin: '+value.username+'\nGerados em '+new Date().toISOString()+'\n\n'+value.codes.join('\n')+'\n\nCada código só pode ser usado uma vez. Não compartilhe.', 'nova-alianca-recuperacao.txt','text/plain');profileDialog('Guarde estes códigos','Eles não serão mostrados novamente.',value.codes.map(c=>'<p><code>'+esc(c)+'</code></p>').join('')+'<p class="help">Um arquivo de texto foi baixado. Guarde-o em local privado e separado do aplicativo.</p>',novaButton('close-nova','Já guardei'))},'Gerar e baixar códigos')}
function novaRecoveryForm(){modal('Recuperar acesso','Funcionários devem pedir uma senha temporária à administração.',field('username','Login do administrador','text',novaAuth.username||'','required autocomplete="username"',true)+field('code','Código de recuperação','text','','required maxlength="80" autocomplete="off"',true)+'<p class="help full">Use um dos códigos guardados anteriormente em Minha conta. Sem eles, será necessário suporte para comprovar e recuperar o acesso.</p>',async f=>{const result=await requestShared('/api/auth/recover',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:f.get('username'),code:f.get('code')})});novaAuth.username=result.username;renderNovaAccess();profileDialog('Acesso recuperado','Entre e escolha uma nova senha pessoal.','<p>Login: <strong>'+esc(result.username)+'</strong></p><p>Senha temporária: <code>'+esc(result.temporaryPassword)+'</code></p><p class="help">Válida por 24 horas e mostrada uma única vez. O código usado foi consumido.</p>',novaButton('close-nova','Ir para o login'))},'Recuperar conta')}

function novaCompleteBackup(){if(pendingChanges)throw Error('Salve as alterações pendentes antes de exportar o backup completo.');modal('Backup completo','Inclui frota, contas, horários, ponto e chamadas.',field('currentPassword','Sua senha atual','password','','required autocomplete="current-password"',true)+field('backupPassword','Senha para proteger o arquivo','password','','required minlength="10" maxlength="128" autocomplete="new-password"',true)+field('confirmPassword','Repita a senha do arquivo','password','','required minlength="10" maxlength="128" autocomplete="new-password"',true)+'<p class="help full">Guarde a senha e o arquivo em local privado. Sessões abertas e códigos de recuperação não são incluídos. Sem a senha do arquivo, ele não poderá ser restaurado.</p>',async f=>{if(f.get('backupPassword')!==f.get('confirmPassword'))throw Error('As senhas do arquivo precisam ser iguais.');const value=await requestShared('/api/backup/export',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({currentPassword:f.get('currentPassword'),backupPassword:f.get('backupPassword')})});novaDownload(value,'nova-alianca-completo-'+dateOnly()+'.json');closeModal();toast('Backup completo protegido baixado.')},'Baixar backup completo')}
function novaRestoreBackup(){if(pendingChanges)throw Error('Salve as alterações pendentes antes de restaurar.');modal('Restaurar backup completo','Substitui todos os registros da empresa.', '<p class="rule-note full">Exporte um backup completo atual antes de continuar. A restauração substitui frota, contas, jornadas e chamadas. Todos precisarão entrar novamente com as senhas existentes no arquivo. Gere novos códigos de recuperação após entrar.</p><label class="full">Arquivo de backup completo<input type="file" name="backupFile" accept=".json,application/json" required></label>'+field('currentPassword','Sua senha atual de administrador','password','','required autocomplete="current-password"',true)+field('backupPassword','Senha do arquivo','password','','required minlength="10" maxlength="128"',true)+field('confirm','Digite RESTAURAR para confirmar','text','','required pattern="RESTAURAR" autocomplete="off"',true),async f=>{const file=f.get('backupFile');if(!file||file.size>3500000)throw Error('Escolha um backup de até 3,5 MB.');let backup;try{backup=JSON.parse(await file.text())}catch{throw Error('Arquivo de backup inválido.')}await requestShared('/api/backup/restore',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({backup,currentPassword:f.get('currentPassword'),backupPassword:f.get('backupPassword'),confirm:f.get('confirm')})});closeModal();novaExpired();toast('Backup restaurado. Entre com uma conta e senha existentes no arquivo.')},'Substituir e restaurar')}
